{////POLYGON ATTRIBUTE FLAGS///////////////////////////}
PAclockwise=64; {phase this out -should be on creation}
PAsetmask3d=not PAclockwise;
PAallselected=512;
PAsomeselected=1024;
PAselected=PAallselected + PAsomeselected;

PAvisible=128;
PAabsolute=32;
PAconnected=16;
PAoutLined=8;
PAsmooth=2;
PAdoubleSided=1;



{////FILLER MODES//////////////////////////////////////}
CMDdots           =130;
CMDlines          =131;
CMDhlines         =132;
CMDCpolygons      =133;
CMDLsource        =135;
