{1 unit = 0.7 degrees}
PersStart=500;
Pers=PersStart;

{////ASSIGNED GLOBAL VARIABLES/////////////////////////}
WAttrib:byte=0;      {global attribute byte}
nodepatt:array[0..4] of byte=(124,68,68,68,124); {pattern for nodes}
Scale:real=0.3;        {scaling value}

