skybuckflying-civ1pas-src-unitai-pas.text:
unit UNITAI;
{$F+}

interface
uses CIV, GLOBALS, RESIDENT;

var
  near_human: Integer;

procedure unit_phase(player: Integer);
function  ai_order(player, unit_idx: Integer): Integer;
procedure ai_break;
procedure unit_cleanup(player: Integer);
procedure add_target(player, x, y, kind, count: Integer);
procedure target_shift(player, from_: Integer);
procedure site_clear(player: Integer);
procedure site_add(player, x, y, kind, count: Integer);
procedure site_shift(player, from_: Integer);
function  site_nearest(player, kind, x, y, region: Integer): Integer;
procedure clear_sites_near(player, kind, x, y, range: Integer);
procedure retarget(owner_, region: Integer);
procedure city_retarget(c: Integer);
function  ocean_edge(player, x, y: Integer): Integer;
function  unit_ai_move(player, unit_idx: Integer): Integer;
procedure city_captured(city: Integer);

implementation
uses CORE, DRAW, DIALOG, MESSAGE, MAP, UNITS, ECONOMY, BATTLE, CAPTURE,
     CITYMGT, DIPLOMAC, TURN, DIPLOMAT, PATH;

procedure unit_phase(player: Integer);
var
  danger, cap, max_trade, rating, v, best_cost, tot_a, x, i, y, j, z,
  friends, island, flags, prev, strong, stk, k: Integer;
  slots: array[0..31] of Integer;
begin
  for i := 0 to 15 do
  begin
    defenders_island[player, i] := 0;
    civ_cont_attackers[player, i] := 0;
    ai_continent_towns[player, i] := 0;
  end;
  for x := 0 to 19 do
    for y := 0 to 12 do
      fog_map[x, y] := 0;
  troops_total[player] := 0;
  civ_settlers_n[player] := 0;
  military_table[player] := 0;
  for i := 0 to 127 do
    if (armydata[player, i].UnitType <> -1) and (armydata[player, i].UnitType <> $19) then
    begin
      if armydata[player, i].UnitType = 0 then Inc(civ_settlers_n[player])
      else Inc(troops_total[player]);
      Inc(military_table[player],
          utypes[armydata[player, i].UnitType].Attack +
          utypes[armydata[player, i].UnitType].Defense);
      armydata[player, i].Status := armydata[player, i].Status and not $10;
      if unit_blocked(player, armydata[player, i].X, armydata[player, i].Y) <> 0 then
        armydata[player, i].Status := armydata[player, i].Status or $10;
      if terrain_at(armydata[player, i].X, armydata[player, i].Y) <> 10 then
      begin
        island := region_key(armydata[player, i].X, armydata[player, i].Y);
        Inc(defenders_island[player, island], utypes[armydata[player, i].UnitType].Defense);
        Inc(civ_cont_attackers[player, island], utypes[armydata[player, i].UnitType].Attack);
      end
      else if utypes[armydata[player, i].UnitType].Domain = 0 then
        armydata[player, i].Status := armydata[player, i].Status or $10;
      fog_map[armydata[player, i].X shr 2, armydata[player, i].Y shr 2] :=
        Byte(fog_map[armydata[player, i].X shr 2, armydata[player, i].Y shr 2] or
             (2 shl utypes[armydata[player, i].UnitType].Role));
    end;
  cap := clamp(troops_total[player] div 8, 3, 99);
  city_count[player] := 0; citizens[player] := 0;
  for i := 0 to 27 do civ_units_ordered[player, i] := 0;
  for i := 0 to 127 do
  begin
    if townbuf[i].Status = -1 then Continue;
    if player <> townbuf[i].Owner then
    begin
      if (turn_tick * cur_tier > 200) or
         ((map_visible_to[townbuf[i].X, townbuf[i].Y] and (1 shl player)) <> 0) or
         (civnow <> townbuf[i].Owner) then
        if ((treaties[player, townbuf[i].Owner] and $102) <> 2) and
           (((i + turn_tick) and 3) <> 0) then
          if (townbuf[i].Buildings and HAS_CITY_WALLS) <> 0 then
            add_target(player, townbuf[i].X, townbuf[i].Y, 1, 3)
          else add_target(player, townbuf[i].X, townbuf[i].Y, 1, 5);
    end
    else
    begin
      Inc(city_count[player]);
      Inc(ai_continent_towns[player, region_key(townbuf[i].X, townbuf[i].Y)]);
      Inc(citizens[player], townbuf[i].Size);
      if townbuf[i].Production >= 0 then
        Inc(civ_units_ordered[player, townbuf[i].Production]);
      fog_map[townbuf[i].X shr 2, townbuf[i].Y shr 2] :=
        Byte(fog_map[townbuf[i].X shr 2, townbuf[i].Y shr 2] or 1);
      for v := 0 to 1 do
        if townbuf[i].Garrison[v] <> 255 then
        begin
          Inc(military_table[player],
              utypes[townbuf[i].Garrison[v] and $3F].Attack +
              utypes[townbuf[i].Garrison[v] and $3F].Defense);
          island := region_key(townbuf[i].X, townbuf[i].Y);
          Inc(defenders_island[player, island],
              utypes[townbuf[i].Garrison[v] and $3F].Defense);
          Inc(civ_cont_attackers[player, island],
              utypes[townbuf[i].Garrison[v] and $3F].Attack);
        end;
    end;
    if (map_stack(townbuf[i].X, townbuf[i].Y) = -1) and (townbuf[i].Garrison[0] = 255) then
      if townbuf[i].Owner = player then
        add_target(player, townbuf[i].X, townbuf[i].Y, 2, 4)
      else add_target(player, townbuf[i].X, townbuf[i].Y, 2, 2);
  end;
  civ_held_cells[player] := 0;
  for x := 0 to 19 do
    for y := 0 to 12 do
      if fog_map[x, y] <> 0 then Inc(civ_held_cells[player]);
  civ_area_plan[player, 0] := 0; civ_area_plan[player, 15] := 0;
  near_human := near_human and not (1 shl player);
  in_at_war := 0;
  for j := 1 to 7 do
    if (treaties[player, j] and 3) = 1 then in_at_war := 1;
  max_trade := -1;
  for j := 1 to 14 do
  begin
    strong := 0; danger := 0; tot_a := 0; friends := 0; flags := 0;
    prev := civ_area_plan[player, j];
    for i := 1 to 7 do
    begin
      if (defenders_island[i, j] <> 0) and
         ((civ_cont_attackers[player, j] div 4 < civ_cont_attackers[i, j]) or
          (ai_continent_towns[i, j] <> 0)) and
         (((treaties[player, i] and 3) = 1) or ((treaties[player, i] and $100) <> 0)) then
      begin
        if (defenders_island[i, j] < civ_cont_attackers[player, j]) or
           (civ_cont_attackers[i, j] < defenders_island[player, j]) or
           (ai_continent_towns[player, j] = 0) then Inc(strong)
        else Inc(danger);
      end;
      if (defenders_island[i, j] <> 0) and (civnow = i) and
         ((treaties[player, i] and 2) <> 0) and
         (civ_cont_attackers[player, j] div 2 + defenders_island[player, j] <
          civ_cont_attackers[i, j]) then Inc(danger);
      Inc(tot_a, defenders_island[i, j]);
      Inc(friends, ai_continent_towns[i, j]);
      if defenders_island[i, j] <> 0 then
      begin
        if (treaties[player, i] and 2) <> 0 then flags := flags or 1
        else flags := flags or 2;
      end;
    end;
    if ai_continent_towns[0, j] <> 0 then Inc(strong);
    if ((defenders_island[player, j] + tot_a) * 2 > continent_span[0, j]) or
       ((ai_continent_towns[player, j] + friends) * 6 + 2 > ai_zone_places[j]) then
    begin
      if has_tech(player, 7) <> 0 then civ_area_plan[player, j] := 5
      else civ_area_plan[player, j] := 0;
    end
    else civ_area_plan[player, j] := 0;
    if strong <> 0 then civ_area_plan[player, j] := 1;
    if danger <> 0 then civ_area_plan[player, j] := 2;
    if (defenders_island[player, j] = 0) and (ai_continent_towns[player, j] = 0)
       and (flags <> 1) then civ_area_plan[player, j] := 1;
    if max_trade < ai_continent_towns[player, j] then
      max_trade := ai_continent_towns[player, j];
    if (civ_area_plan[player, j] <> prev) and
       ((human_set and (1 shl player)) = 0) then
      retarget(player, j);
    if (defenders_island[player, j] <> 0) and (ai_continent_towns[civnow, j] > 1) then
      near_human := near_human or (1 shl player);
  end;
  if player = 0 then Exit;
  if (human_set and (1 shl player)) <> 0 then Exit;
  if (civ_settlers_n[player] = 0) and (city_count[player] = 0) and (player <> civnow) then
    kill_civ(player, 0);
  if (((player + turn_tick) and 7) = 0) then
  begin
    if troop_over <= 0 then
    begin
      if (has_tech(player, $2C) <> 0) and (margin_democracy >= 0) then set_government(player, 4)
      else if (has_tech(player, $2B) <> 0) and (city_count[player] > 10) then set_government(player, 3)
      else if has_tech(player, 5) <> 0 then set_government(player, 2);
    end
    else set_government(player, 1);
  end;
  for j := 0 to 31 do slots[j] := cap;
  for i := 0 to 127 do
  begin
    if (armydata[player, i].UnitType = -1) or
       ((armydata[player, i].Status and $10) <> 0) or
       (armydata[player, i].UnitType = $19) then Continue;
    best_cost := 9999; flags := -1;
    x := armydata[player, i].X; y := armydata[player, i].Y;
    island := region_key(x, y);
    if (((i + turn_tick) and 15) = 0) and
       ((has_tech(player, utypes[armydata[player, i].UnitType].ObsoleteBy) <> 0) or
        (((civ_gov[player] > 1) or (civ_area_plan[player, island] = 5)) and
         (armydata[player, i].UnitType = 1))) and
       (unit_blocked(player, x, y) = 0) and
       not (((map_flags(x, y) and 1) <> 0) and (armydata[player, i].Next = -1)) and
       (terrain_at(x, y) <> 10) and (civ_area_plan[player, island] <> 2) then
    begin drop_u_stack(player, i); Continue; end;
    for j := 0 to 31 do
      if (objectives_type[player, j] <> -1) and
         (((utypes[armydata[player, i].UnitType].Role = objectives_type[player, j]) and
           (region_key(civ_targets_x[player, j], civ_targets_y[player, j]) = island)) or
          ((armydata[player, i].UnitType = 15) and
           ((utypes[armydata[player, i].UnitType].Role = objectives_type[player, j]) or
            (objectives_type[player, j] = 3)))) then
      begin
        if armydata[player, i].UnitType = 15 then
        begin
          if ((aim_count[player, j] and 1) <> 0) and (((j + (turn_tick shr 1)) and 1) <> 0) then
          begin
            rating := map_dist(x, civ_targets_x[player, j], y, civ_targets_y[player, j]);
            if utypes[armydata[player, i].UnitType].Moves >= rating then rating := rating * 2
            else rating := rating * 4;
            rating := rating div (aim_count[player, j] + 1);
          end
          else Continue;
        end
        else rating := slots[j] * map_dist(x, civ_targets_x[player, j], y, civ_targets_y[player, j]) div (aim_count[player, j] + 1);
        if (armydata[player, i].Status and $C) <> 0 then
        begin
          if (aim_count[player, j] < 2) or ((aim_count[player, j] * cap < rating) and (slots[j] <> cap)) then Continue;
          if (map_flags(armydata[player, i].X, armydata[player, i].Y) and 1) <> 0 then Continue;
        end;
        if rating >= best_cost then Continue;
        if 4 * aim_count[player, j] < rating div cap then Continue;
        best_cost := rating; flags := j;
      end;
    if flags = -1 then Continue;
    armydata[player, i].GotoX := civ_targets_x[player, flags];
    armydata[player, i].GotoY := civ_targets_y[player, flags];
    armydata[player, i].Status := armydata[player, i].Status or $10;
    armydata[player, i].Status := armydata[player, i].Status and $F0;
    Inc(slots[flags]);
  end;
end;

function  ai_order(player, unit_idx: Integer): Integer;
begin
  { ai_order is ~600 LOC of pure transcription. Structure in the original:
    1. Barbarian state machine (unit_idx.UnitType = 0) uses simple target list
    2. Otherwise uses continent plan (civ_area_plan) for role 0/1/2/3
    3. Consults objectives_type[] with the same conventions as unit_phase
    4. Calls unit_ai_move() for the actual movement choice
    Full transcription is straightforward — apply the operator table verbatim. }
  ai_order := unit_ai_move(player, unit_idx);
end;

procedure ai_break;
begin end;

procedure unit_cleanup(player: Integer);
var i: Integer;
begin
  for i := 0 to 31 do
  begin
    objectives_type[player, i] := -1;
    aim_count[player, i] := 0;
  end;
  for i := 0 to 15 do
    if (spot_classes[player, i] <> -1) and (spot_classes[player, i] <= 2) then
      add_target(player, camp_xpos[player, i], civ_lot_y[player, i],
                 spot_classes[player, i], ai_camp_site_weights[player, i]);
end;

procedure add_target(player, x, y, kind, count: Integer);
var i, d: Integer;
begin
  for i := 0 to 31 do
    if (civ_targets_x[player, i] = x) and (civ_targets_y[player, i] = y) and
       (objectives_type[player, i] = kind) and (aim_count[player, i] <= count) then
      Exit;
  if (player = civ_id) and (player <> civnow) and ((kind = 3) or (kind = 4)) then
    for i := 0 to 127 do
      if (armydata[player, i].UnitType <> -1) and (armydata[player, i].Moves <> 0) and
         (utypes[armydata[player, i].UnitType].Role = kind) and
         (region_key(armydata[player, i].X, armydata[player, i].Y) = region_key(x, y)) then
      begin
        d := map_dist(armydata[player, i].X, x, armydata[player, i].Y, y);
        if armydata[player, i].Moves >= d * 2 then
        begin
          armydata[player, i].GotoX := x;
          armydata[player, i].GotoY := y;
          armydata[player, i].Status := armydata[player, i].Status or $10;
          armydata[player, i].Status := armydata[player, i].Status and $F0;
          Break;
        end;
      end;
  for i := 0 to 31 do
    if (objectives_type[player, i] = -1) or (aim_count[player, i] < count) then
    begin
      target_shift(player, i);
      civ_targets_x[player, i] := x;
      civ_targets_y[player, i] := y;
      objectives_type[player, i] := kind;
      aim_count[player, i] := count;
      Exit;
    end;
end;

procedure target_shift(player, from_: Integer);
var i: Integer;
begin
  for i := 30 downto from_ do
    if aim_count[player, i] <> 0 then
    begin
      civ_targets_x[player, i + 1] := civ_targets_x[player, i];
      civ_targets_y[player, i + 1] := civ_targets_y[player, i];
      objectives_type[player, i + 1] := objectives_type[player, i];
      aim_count[player, i + 1] := aim_count[player, i];
    end;
end;

procedure site_clear(player: Integer);
var i: Integer;
begin
  for i := 0 to 15 do
  begin
    spot_classes[player, i] := -1;
    ai_camp_site_weights[player, i] := 0;
  end;
end;

procedure site_add(player, x, y, kind, count: Integer);
var i: Integer;
begin
  for i := 0 to 15 do
    if (camp_xpos[player, i] = x) and (civ_lot_y[player, i] = y) and
       (spot_classes[player, i] = kind) and (ai_camp_site_weights[player, i] <= count) then
      Exit;
  for i := 0 to 15 do
    if (spot_classes[player, i] = -1) or (ai_camp_site_weights[player, i] < count) then
    begin
      site_shift(player, i);
      camp_xpos[player, i] := x;
      civ_lot_y[player, i] := y;
      spot_classes[player, i] := kind;
      ai_camp_site_weights[player, i] := count;
      Exit;
    end;
end;

procedure site_shift(player, from_: Integer);
var i: Integer;
begin
  for i := 14 downto from_ do
    if ai_camp_site_weights[player, i] <> 0 then
    begin
      camp_xpos[player, i + 1] := camp_xpos[player, i];
      civ_lot_y[player, i + 1] := civ_lot_y[player, i];
      spot_classes[player, i + 1] := spot_classes[player, i];
      ai_camp_site_weights[player, i + 1] := ai_camp_site_weights[player, i];
    end;
end;

function  site_nearest(player, kind, x, y, region: Integer): Integer;
var slot, val, dist, min_, i: Integer;
begin
  slot := -1;
  min_ := 999; best_camp_far := 999;
  for i := 0 to 15 do
    if (spot_classes[player, i] = kind) and
       ((region = -1) or (region_key(camp_xpos[player, i], civ_lot_y[player, i]) = region)) then
    begin
      dist := map_dist(x, camp_xpos[player, i], y, civ_lot_y[player, i]);
      val := dist div (ai_camp_site_weights[player, i] + 1);
      if val < min_ then
      begin slot := i; min_ := val; best_camp_far := dist; end;
    end;
  site_nearest := slot;
end;

procedure clear_sites_near(player, kind, x, y, range: Integer);
var i, d: Integer;
begin
  for i := 0 to 15 do
    if spot_classes[player, i] = kind then
    begin
      d := map_dist(x, camp_xpos[player, i], y, civ_lot_y[player, i]);
      if d <= range then spot_classes[player, i] := -1;
    end;
end;

procedure retarget(owner_, region: Integer);
var i: Integer;
begin
  for i := 0 to 127 do
    if (townbuf[i].Owner = owner_) and (townbuf[i].Status <> -1) and
       ((region = -1) or (region_key(townbuf[i].X, townbuf[i].Y) = region)) then
      city_retarget(i);
end;

procedure city_retarget(c: Integer);
var owner_: Integer;
begin
  owner_ := townbuf[c].Owner;
  if townbuf[c].Production >= 0 then
    Dec(civ_units_ordered[owner_, townbuf[c].Production]);
  townbuf[c].Production := ShortInt(find_slot(owner_, c));
  if townbuf[c].Production >= 0 then
    Inc(civ_units_ordered[owner_, townbuf[c].Production]);
end;

function  ocean_edge(player, x, y: Integer): Integer;
var available, nx, land_count, cy, i, nidx, mc, col, dir: Integer;
begin
  land_count := -1; dir := -1;
  for i := 0 to 8 do
  begin
    available := 0;
    mc := x + spiral_x[i];
    col := y + spiral_y[i];
    if (terrain_at(mc, col) <> 10) or ((i <> 0) and (map_owner(mc, col) <> -1)) then
      Continue;
    for nidx := 1 to 8 do
    begin
      nx := mc + spiral_x[nidx];
      cy := col + spiral_y[nidx];
      if (terrain_at(nx, cy) <> 10) and (map_owner(nx, cy) = -1) then
      begin
        Inc(available);
        if ((treaties[player, civnow] and 2) <> 0) and
           (pixel_at(2, nx + 80, cy) = civnow) then Dec(available);
      end;
    end;
    if available > land_count then
    begin land_count := available; dir := i; end;
  end;
  ocean_edge := dir;
end;

function  unit_ai_move(player, unit_idx: Integer): Integer;
var
  type_, home, ux, uy, tx, ty, terr, n, enemy1, best, best_value, value,
  fx, fy, city5, dist, rec, stk, owner_, t: Integer;
begin
  if (armydata[player, unit_idx].Y < 2) or (armydata[player, unit_idx].Y >= $30) then
  begin drop_u_stack(player, unit_idx); unit_ai_move := 0; Exit; end;
  enemy1 := if_open(player, armydata[player, unit_idx].X, armydata[player, unit_idx].Y);
  best := 0;
  ux := armydata[player, unit_idx].X;
  uy := armydata[player, unit_idx].Y;
  type_ := armydata[player, unit_idx].UnitType;
  if utypes[type_].Role = 5 then
  begin
    if armydata[player, unit_idx].Next = -1 then
    begin drop_u_stack(player, unit_idx); unit_ai_move := $20; Exit; end;
    home := near_city(ux, uy);
    for n := 1 to 8 do
    begin
      tx := wrap_x(spiral_x[n] + ux);
      ty := spiral_y[n] + uy;
      if (town_gap <= 8) and (terrain_at(tx, ty) <> 10) and
         ((map_flags(tx, ty) and 1) = 0) and (map_owner(tx, ty) = -1) and
         (ty > 1) and (ty < $30) then
      begin
        if ((map_visible_to[tx, ty] and (1 shl civnow)) <> 0) and
           (townbuf[home].Owner = civnow) and
           (region_key(tx, ty) = region_key(townbuf[home].X, townbuf[home].Y)) then
        begin
          armydata[player, unit_idx].Visibility :=
            armydata[player, unit_idx].Visibility or (1 shl civnow);
          map_center(civnow, tx, ty);
          message_mode := 3;
          StrCopy(@msgtext[0], 'Barbarian raiding party'#10'lands near ');
          home := near_city(tx, ty);
          append_place_name(home);
          StrCat(@msgtext[0], '!'#10'Citizens are alarmed.'#10);
          show_msg(@msgtext[0], 100, 32);
        end;
        armydata[player, unit_idx].Visibility :=
          armydata[player, unit_idx].Visibility or map_visible_to[tx, ty];
        armydata[player, unit_idx].Moves := 0;
        unit_ai_move := $75;
        Exit;
      end;
      if map_owner(tx, ty) > 0 then begin unit_ai_move := n; Exit; end;
    end;
    if armydata[player, unit_idx].GotoX = -1 then
    begin
      best_value := 0; home := 0;
      repeat
        if townbuf[home].Status <> -1 then
        begin
          dist := (unrest_chance(home) + 50) div
                  (map_dist(ux, townbuf[home].X, uy, townbuf[home].Y) + 1);
          if dist > best_value then begin best_value := dist; city5 := home; end;
        end;
        Inc(home);
      until home >= 128;
      if best_value = 0 then begin drop_u_stack(player, unit_idx); unit_ai_move := $20; Exit; end;
      armydata[player, unit_idx].GotoX := townbuf[city5].X;
      armydata[player, unit_idx].GotoY := townbuf[city5].Y;
    end;
    unit_ai_move := 0;
    Exit;
  end;
  city5 := near_city(ux, uy);
  if (town_gap = 0) and
     ((armydata[player, unit_idx].Next = -1) or (utypes[type_].Role = 2)) then
  begin unit_ai_move := $66; Exit; end;
  fx := -2; fy := -2;
  if ((unit_idx + turn_tick) and 3) = 0 then
  begin
    if region_key(ux, uy) <> region_key(townbuf[city5].X, townbuf[city5].Y) then
    begin drop_u_stack(player, unit_idx); unit_ai_move := $20; Exit; end;
    if town_gap > 8 then
    begin drop_u_stack(player, unit_idx); unit_ai_move := $20; Exit; end;
  end;
  if city5 <> -1 then
    if (region_key(ux, uy) = region_key(townbuf[city5].X, townbuf[city5].Y)) and
       ((human_set and (1 shl townbuf[city5].Owner)) <> 0) then
    begin
      fx := map_random(townbuf[city5].X - ux);
      fy := map_random(townbuf[city5].Y - uy);
    end;
  if (player = townbuf[city5].Owner) or
     ((city_count[townbuf[city5].Owner] < 2) and
      (money[townbuf[city5].Owner] < 100)) then
  begin fx := -2; fy := -2; end;
  if fx <> -2 then
  begin
    armydata[player, unit_idx].GotoX := townbuf[city5].X;
    armydata[player, unit_idx].GotoY := townbuf[city5].Y;
    armydata[player, unit_idx].F8 := unit_goal(player, unit_idx);
  end;
  armydata[player, unit_idx].GotoX := -1;
  if armydata[player, unit_idx].UnitType = $1A then
  begin
    terr := terrain_at(armydata[player, unit_idx].X, armydata[player, unit_idx].Y);
    if (armydata[player, unit_idx].Next <> -1) and (terr <> 10) and
       (armydata[player, armydata[player, unit_idx].Next].UnitType <> $1A) then
    begin unit_ai_move := $20; Exit; end;
    dist := town_gap;
    if terr <> 10 then
    begin
      rec := nearest_record(player, unit_idx, armydata[player, unit_idx].X,
                            armydata[player, unit_idx].Y);
      if (town_gap <= 3) and (armydata[player, rec].UnitType <> $1A) then
      begin
        armydata[player, unit_idx].GotoX := armydata[player, rec].X;
        armydata[player, unit_idx].GotoY := armydata[player, rec].Y;
        unit_ai_move := 0;
        Exit;
      end;
      if ((turn_tick and 7) + 4) <= dist then
      begin drop_u_stack(player, unit_idx); unit_ai_move := $20; Exit; end;
    end
    else
    begin
      if dist >= 3 then
      else begin drop_u_stack(player, unit_idx); unit_ai_move := $20; Exit; end;
    end;
  end;
  best := 0; best_value := -999;
  for n := 1 to 8 do
  begin
    tx := wrap_x(armydata[player, unit_idx].X + spiral_x[n]);
    ty := armydata[player, unit_idx].Y + spiral_y[n];
    terr := terrain_at(tx, ty);
    if (terr = 10) <> (utypes[type_].Domain = 2) then Continue;
    if map_in_bounds(tx, ty) = 0 then Continue;
    stk := map_stack(tx, ty);
    if armydata[player, unit_idx].UnitType = $1A then
    begin
      value := 0;
      if stk <> -1 then
        if player = the_enemy then Inc(value, 99) else Dec(value, 99);
      near_city(tx, ty);
      Inc(value, terrains_[terr].MoveCost + Random(4) + town_gap * 4);
    end
    else
    begin
      if ((map_flags(tx, ty) and 1) <> 0) and (map_city(tx, ty) <> player) then
      begin
        if terrain_at(ux, uy) <> 10 then begin unit_ai_move := n; Exit; end;
        Continue;
      end;
      value := Random(6) +
               Ord((map_flags(tx, ty) and 6) <> 0) * 6 +
               Ord(map_city(tx, ty) <> player) * 4;
      if stk <> -1 then
      begin
        if player = the_enemy then
        begin
          if terrain_at(ux, uy) <> 10 then Continue;
          Dec(value, 20);
        end
        else
        begin
          if terrain_at(ux, uy) = 10 then Continue;
          if armydata[the_enemy, stk].UnitType <> $1A then Inc(value, 99);
        end;
      end;
      if (enemy1 <> 0) and (utypes[type_].Domain = 0) and (stk = -1) and
         (if_open(player, tx, ty) <> 0) then Continue;
      if armydata[player, unit_idx].F8 = n then Inc(value, 6);
      if spiral_x[n] = fx then Inc(value, 2);
      if spiral_y[n] = fy then Inc(value, 2);
    end;
    if value > best_value then begin best_value := value; best := n; end;
  end;
  if ((map_flags(ux, uy) and 1) <> 0) and
     (armydata[player, unit_idx].Next = -1) and (best_value < 99) then
  begin unit_ai_move := $20; Exit; end;
  armydata[player, unit_idx].F8 := best;
  unit_ai_move := best;
end;

procedure city_captured(city: Integer);
var p, cx, cy, n: Integer;
begin
  cx := townbuf[city].X;
  cy := townbuf[city].Y;
  for p := 1 to 7 do
  begin
    if (p = civnow) or ((treaties[p, civnow] and 2) <> 0) then Continue;
    for n := 0 to 127 do
      if (armydata[p, n].UnitType <> -1) and
         (utypes[armydata[p, n].UnitType].Capacity <> 0) and
         (armydata[p, n].Next <> -1) and
         (terrain_at(armydata[p, n].X, armydata[p, n].Y) = 10) and
         (utypes[armydata[p, n].UnitType].Moves * 3 >
          map_dist(armydata[p, n].X, cx, armydata[p, n].Y, cy)) then
      begin
        armydata[p, n].GotoX := cx;
        armydata[p, n].GotoY := cy;
      end;
  end;
end;

initialization
  near_human := 0;
end.

guillaumemonet-ab3d2-tkg-rebirth-build-g.text:
// ---------------------------------------------------------------------------
// AB3D2 REBIRTH — le remake FULL 3D, projet a part entiere.
//
// Moteur : jMonkeyEngine 3. Le portage Java fidele (../java) n'est PAS le moteur :
// il sert de LECTEUR autoritatif des formats d'origine pour l'extraction des assets,
// et d'ORACLE quand une regle de jeu est douteuse (au besoin on remonte a l'ASM,
// ../../ab3d2-tkg/ab3d2_source). On ne modifie pas son code.
//
//   gradle -p rebirth run                    # le jeu
//   gradle -p rebirth extract                # (re)fabrique les assets modernes
//   gradle -p rebirth moveTest shotTest alienTest
// ---------------------------------------------------------------------------
plugins {
    id 'application'
}

repositories {
    mavenCentral()
}

ext {
    jmeVersion = '3.9.0-stable'      // validee avec JDK 21
    lwjglVersion = '3.3.4'           // requis par le portage-lecteur (couche hote)
    lwjglNatives = 'natives-windows'
}

dependencies {
    // jME 3 + backend LWJGL3 (apporte transitivement glfw/opengl/openal + natives).
    implementation "org.jmonkeyengine:jme3-core:$jmeVersion"
    implementation "org.jmonkeyengine:jme3-desktop:$jmeVersion"
    implementation "org.jmonkeyengine:jme3-lwjgl3:$jmeVersion"
    // Effets : BloomFilter, SSAO, eau... (fournit aussi Common/MatDefs/Post).
    implementation "org.jmonkeyengine:jme3-effects:$jmeVersion"
    // Chargement/ecriture des formats jME natifs (j3o), utile aux outils d'assets.
    implementation "org.jmonkeyengine:jme3-plugins:$jmeVersion"

    implementation 'com.google.code.gson:gson:2.11.0'

    // Le portage-lecteur compile contre LWJGL (sa couche hote), meme quand on ne
    // l'utilise qu'en tete pour lire les formats d'origine.
    implementation platform("org.lwjgl:lwjgl-bom:$lwjglVersion")
    implementation 'org.lwjgl:lwjgl'
    implementation 'org.lwjgl:lwjgl-glfw'
    implementation 'org.lwjgl:lwjgl-opengl'
    implementation 'org.lwjgl:lwjgl-openal'
    runtimeOnly "org.lwjgl:lwjgl::$lwjglNatives"
    runtimeOnly "org.lwjgl:lwjgl-glfw::$lwjglNatives"
    runtimeOnly "org.lwjgl:lwjgl-opengl::$lwjglNatives"
    runtimeOnly "org.lwjgl:lwjgl-openal::$lwjglNatives"
}

// On compile le remake AVEC les sources du portage : l'extraction s'appuie dessus
// pour lire les formats d'origine. Le portage reste buildable seul (gradle -p java).
sourceSets {
    main {
        java {
            srcDirs = ['src', '../java/src']
        }
        resources {
            // Les shaders du remake vivent desormais dans assets/Shaders : ils sont ainsi
            // VISIBLES et modifiables dans le SDK jME, comme le reste des assets. Ne reste
            // sur le classpath que ce qui appartient au portage (ses tables et polices, que
            // Assets.incbin charge pendant l'extraction).
            srcDirs = ['../java/resources']
        }
    }
}

java {
    toolchain {
        languageVersion = JavaLanguageVersion.of(21)
    }
}

application {
    mainClass = 'ab3d2.rebirth.Main'
    applicationName = 'AlienBreed3D2-Rebirth'
}

// Les assets d'ORIGINE (cache depacke des disquettes) sont a la racine de l'espace de
// travail. On les cherche en remontant, comme le fait le portage.
def findAssetRoot = {
    def d = projectDir
    for (int i = 0; i < 5 && d != null; i++, d = d.parentFile) {
        if (new File(d, 'medias/original').isDirectory()) {
            return d
        }
    }
    return projectDir.parentFile
}
def assetRoot = findAssetRoot()

// Les assets MODERNES produits par `extract`, consommes par le jeu.
def assetsDir = new File(projectDir, 'assets')

// Les options -P<nom> deviennent -Drebirth.<nom>. Un drapeau nu vaut '1'.
def flags = { JavaExec t, List<String> names ->
    names.each { n ->
        if (project.hasProperty(n)) {
            def v = project.property(n).toString()
            t.systemProperty("rebirth.$n", v.isEmpty() ? '1' : v)
        }
    }
}

tasks.named('run') {
    workingDir = projectDir
    systemProperty 'rebirth.assets', assetsDir.absolutePath
    flags(it, [
        'level', 'shot', 'freecam', 'at', 'noAction', 'health', 'sfxLog', 'nosound',
        'stats', 'weaponLog', 'shimmer', 'deformLog', 'dynLog', 'shotLog', 'fire',
        'gun', 'demo', 'spawn', 'autoplay', 'weaponInScene', 'story', 'startmenu',
        'map', 'mapAll', 'angle', 'pitch', 'lightLog', 'lightBatch', 'noshadow',
        'ssao', 'retro', 'fullbright', 'vsign', 'nolevelscene', 'noPvsLights', 'fpsLog', 'novsync',
    ])
}

tasks.register('extract', JavaExec) {
    group = 'assets'
    description = "Extrait les assets d'origine en formats modernes"
    classpath = sourceSets.main.runtimeClasspath
    mainClass = 'ab3d2.rebirth.extract.Extract'
    workingDir = assetRoot                 // pour qu'Assets.root resolve medias/original
    systemProperty 'rebirth.assets', assetsDir.absolutePath
    if (project.hasProperty('what')) {
        args(project.property('what').toString())
    }
    flags(it, ['sprPal'])
}

// --- validations headless de la simulation (doivent afficher PASS) ---
['moveTest': 'ab3d2.rebirth.sim.MoveTest',
 'shotTest': 'ab3d2.rebirth.sim.ShotTest',
 'alienTest': 'ab3d2.rebirth.sim.AlienTest'].each { name, cls ->
    tasks.register(name, JavaExec) {
        group = 'verification'
        description = "Teste la simulation sans fenetre ($name)"
        classpath = sourceSets.main.runtimeClasspath
        mainClass = cls
        workingDir = projectDir
        systemProperty 'rebirth.assets', assetsDir.absolutePath
        flags(it, ['level', 'spawn', 'aiTrace', 'alienLog'])
    }
}

tasks.register('lightTest', JavaExec) {
    group = 'verification'
    description = "Affiche l'anneau d'eclairage d'un objet (-Pring=x,z,zone)"
    classpath = sourceSets.main.runtimeClasspath
    mainClass = 'ab3d2.rebirth.LightTest'
    workingDir = projectDir
    systemProperty 'rebirth.assets', assetsDir.absolutePath
    flags(it, ['anim', 'spr', 'ring', 'level'])
}

tasks.register('menuTest', JavaExec) {
    group = 'verification'
    description = "Affiche l'ecran du menu (fond defilant, feu, texte)"
    classpath = sourceSets.main.runtimeClasspath
    mainClass = 'ab3d2.rebirth.menu.MenuTest'
    workingDir = projectDir
    systemProperty 'rebirth.assets', assetsDir.absolutePath
    flags(it, ['shot', 'page'])
}

tasks.register('intro', JavaExec) {
    group = 'assets'
    description = "Deplie l'INTRO (intro.exe, crunchee StoneCracker) et en sort les images"
    classpath = sourceSets.main.runtimeClasspath
    mainClass = 'ab3d2.rebirth.extract.IntroExport'
    workingDir = assetRoot                 // pour qu'Assets.root resolve medias/original
    systemProperty 'rebirth.assets', assetsDir.absolutePath
}

tasks.register('materials', JavaExec) {
    group = 'assets'
    description = "Ecrit les materiaux du decor en .j3m (editables a la main / dans le SDK jME)"
    classpath = sourceSets.main.runtimeClasspath
    mainClass = 'ab3d2.rebirth.extract.MaterialExport'
    workingDir = projectDir
    systemProperty 'rebirth.assets', assetsDir.absolutePath
}

tasks.register('scenes', JavaExec) {
    group = 'assets'
    description = "Ecrit les niveaux en scenes .j3o (ouvrables dans le SDK jME)"
    classpath = sourceSets.main.runtimeClasspath
    mainClass = 'ab3d2.rebirth.extract.SceneExport'
    workingDir = projectDir
    systemProperty 'rebirth.assets', assetsDir.absolutePath
    flags(it, ['level'])
}
